import 'dart:async';import 'package:flutter/material.dart';import '../../core/addons/application/addon_install_controller.dart';import '../../core/runtime/legacy/legacy_service_supervisor.dart';class ServicesPage extends StatelessWidget{const ServicesPage({required this.addonInstallController,required this.serviceSupervisor,super.key});final AddonInstallController addonInstallController;final LegacyServiceSupervisor serviceSupervisor;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Serviços'),actions:[IconButton(onPressed:()=>unawaited(serviceSupervisor.reconcile()),icon:const Icon(Icons.refresh))]),body:AnimatedBuilder(animation:Listenable.merge([addonInstallController,serviceSupervisor]),builder:(_,__){final s=addonInstallController.installedAddons.where((a)=>a.manifest.isPythonService).toList();if(s.isEmpty)return const Center(child:Text('Nenhum serviço Kodi instalado'));return ListView(padding:const EdgeInsets.all(24),children:[for(final a in s)Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(title:Text(a.manifest.name),subtitle:Text(serviceSupervisor.errors[a.manifest.id]??(serviceSupervisor.runningAddonIds.contains(a.manifest.id)?'Rodando':'Parado')),trailing:IconButton(onPressed:()=>unawaited(serviceSupervisor.restart(a.manifest.id)),icon:const Icon(Icons.restart_alt))))]);}));}
